import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import { Game, HudState, RunResult } from './game/engine';
import { diffById, loadSave, SaveData, storeSave } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY_HUD: HudState = { money: 0, time: 0, heat: 1, stars: 1, hp: 100, nitro: 1, kmh: 0, bust: 0, evade: 0, heli: false, lit: false, cops: 0, puncture: false };

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RunResult; record: boolean } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onEvent: (text, color) => {
        const id = ++toastId.current;
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 1600));
      },
      onOver: r => {
        const prev = saveRef.current, record = r.score > prev.best;
        persist({
          ...prev, best: Math.max(prev.best, r.score), bestStars: Math.max(prev.bestStars, r.stars),
          bestTime: Math.max(prev.bestTime, r.time), runs: prev.runs + 1, loot: prev.loot + r.money,
        });
        // Pequeña espera para ver el arresto antes del resumen.
        timers.current.push(window.setTimeout(() => {
          setResult({ r, record }); go('over');
          if (record) { try { confetti({ particleCount: 150, spread: 100, origin: { y: 0.35 }, colors: ['#ff2a3d', '#2a6bff', '#ffd23f', '#3dff7a'] }); } catch { /* sin confeti */ } }
        }, 1200));
      },
    });
    gameRef.current = game;
    return () => { timers.current.forEach(t => window.clearTimeout(t)); timers.current = []; game.dispose(); gameRef.current = null; };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init(); sound.click();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud(EMPTY_HUD);
    g.newGame(diffById(saveRef.current.diff));
    go('play');
  }, []);

  const toMenu = useCallback(() => { gameRef.current?.toAttract(); setToasts([]); go('menu'); }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === 'Escape' || e.code === 'KeyP') {
        if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
      } else if (e.code === 'Enter' && (screenRef.current === 'menu' || screenRef.current === 'over')) start();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused, start]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const radarRef = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.attachRadar(c); }, []);

  return (
    <div className="pc-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#060912]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="pc-vignette absolute inset-0" />
      <div className="pc-scan absolute inset-0" />

      {screen === 'menu' && (
        <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start}
          onDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }} />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          radarRef={radarRef} onPause={() => setPaused(true)} onMute={toggleMute} />
      )}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}

      {screen === 'over' && result && (
        <GameOver r={result.r} record={result.record} best={save.best} onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp, Clock, Flame, Heart, Pause, Plane, Siren, Star, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import { formatMoney, formatTime, MAX_STARS } from '../game/config';
import { HudState } from '../game/engine';
import { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string }

interface Props {
  hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad;
  radarRef(c: HTMLCanvasElement | null): void; onPause(): void; onMute(): void;
}

function Bar({ value, color, icon, label, warn }: { value: number; color: string; icon: React.ReactNode; label: string; warn?: boolean }) {
  return (
    <div className="flex items-center gap-2">
      <div className={clsx('grid h-7 w-7 place-items-center rounded-lg bg-black/40', warn && 'pc-blink')} style={{ color }}>{icon}</div>
      <div className="flex-1">
        <div className="mb-0.5 flex justify-between text-[10px] font-bold uppercase tracking-widest text-white/55"><span>{label}</span><span>{Math.round(value * 100)}%</span></div>
        <div className="h-2.5 overflow-hidden rounded-full bg-white/10">
          <div className="h-full rounded-full transition-[width] duration-150" style={{ width: `${Math.max(0, Math.min(1, value)) * 100}%`, background: color, boxShadow: `0 0 10px ${color}` }} />
        </div>
      </div>
    </div>
  );
}

function TouchBtn({ k, pad, className, children }: { k: keyof VirtualPad; pad: VirtualPad; className?: string; children: React.ReactNode }) {
  const set = (v: boolean) => (e: React.PointerEvent) => { e.preventDefault(); pad[k] = v; };
  return (
    <button onPointerDown={set(true)} onPointerUp={set(false)} onPointerLeave={set(false)} onPointerCancel={set(false)}
      className={clsx('pc-glass pointer-events-auto grid place-items-center text-white active:bg-white/25', className)}>{children}</button>
  );
}

export default function Hud({ hud, toasts, muted, touch, pad, radarRef, onPause, onMute }: Props) {
  const frac = hud.heat - Math.floor(hud.heat);
  return (
    <div className="pointer-events-none absolute inset-0">
      {hud.bust > 0.05 && <div className="pc-alarm absolute inset-0" style={{ opacity: hud.bust }} />}
      {hud.hp < 30 && <div className="pc-hurt pc-blink absolute inset-0" />}

      {/* Botín y tiempo */}
      <div className="pc-glass absolute left-3 top-3 px-4 py-2 sm:left-5 sm:top-4">
        <div className="text-[10px] font-bold uppercase tracking-[0.3em] text-[#3dff7a]/80">Botín</div>
        <div className="pc-mono text-2xl font-black text-[#3dff7a] sm:text-3xl" style={{ textShadow: '0 0 14px rgba(61,255,122,0.5)' }}>{formatMoney(hud.money)}</div>
        <div className="flex items-center gap-1.5 text-xs text-white/65"><Clock size={12} /> <span className="pc-mono">{formatTime(hud.time)}</span><span className="ml-2">· {hud.cops} patrullas</span></div>
      </div>

      {/* Nivel de búsqueda */}
      <div className="absolute left-1/2 top-3 -translate-x-1/2 text-center sm:top-4">
        <div className="pc-glass flex items-center gap-1 px-3 py-2">
          {Array.from({ length: MAX_STARS }, (_, i) => (
            <Star key={i} size={26} fill="currentColor" className={clsx('pc-star', i < hud.stars && 'on', i < hud.stars && hud.bust > 0.2 && 'flash')} />
          ))}
        </div>
        <div className="mx-auto mt-1 h-1 w-40 overflow-hidden rounded-full bg-white/10">
          <div className="h-full bg-[#ffd23f]" style={{ width: `${hud.stars >= MAX_STARS ? 100 : frac * 100}%` }} />
        </div>
        <div className="mt-1 flex justify-center gap-2 text-[11px] font-bold uppercase tracking-wider">
          {hud.heli && <span className={clsx('flex items-center gap-1', hud.lit ? 'pc-blink text-white' : 'text-[#9fd0ff]')}><Plane size={12} /> {hud.lit ? 'Te iluminan' : 'Helicóptero'}</span>}
          {hud.puncture && <span className="pc-blink text-[#ff5a3c]">Pinchazo</span>}
        </div>
        {/* Avisos */}
        <div className="mt-2 flex flex-col items-center gap-1">
          {toasts.map(t => (
            <div key={t.id} className="pc-toast pc-display text-2xl sm:text-3xl" style={{ color: t.color, textShadow: `0 0 16px ${t.color}, 0 2px 0 #000` }}>{t.text}</div>
          ))}
        </div>
      </div>

      {/* Botones */}
      <div className="absolute right-3 top-3 flex gap-2 sm:right-5 sm:top-4">
        <button onClick={onMute} aria-label="Sonido" className="pc-glass pointer-events-auto grid h-11 w-11 place-items-center">{muted ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
        <button onClick={onPause} aria-label="Pausa" className="pc-glass pointer-events-auto grid h-11 w-11 place-items-center"><Pause size={20} /></button>
      </div>

      {/* Arresto / evasión */}
      {hud.bust > 0.03 && (
        <div className="absolute left-1/2 top-[58%] w-64 -translate-x-1/2 text-center">
          <div className="pc-display pc-blink mb-1 flex items-center justify-center gap-2 text-2xl text-[#ff3b4e]"><Siren size={22} /> ¡Te rodean!</div>
          <div className="h-3 overflow-hidden rounded-full border border-white/30 bg-black/50"><div className="h-full bg-gradient-to-r from-[#ff2a3d] to-[#2a6bff]" style={{ width: `${hud.bust * 100}%` }} /></div>
          <div className="mt-1 text-xs text-white/70">¡Acelera para escapar!</div>
        </div>
      )}
      {hud.evade > 0.05 && hud.bust <= 0.03 && (
        <div className="absolute left-1/2 top-[22%] w-52 -translate-x-1/2 text-center sm:top-[24%]">
          <div className="mb-1 text-xs font-bold uppercase tracking-widest text-[#3dff9a]">Despistando…</div>
          <div className="h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full bg-[#3dff9a]" style={{ width: `${hud.evade * 100}%` }} /></div>
        </div>
      )}

      {/* Radar */}
      <div className={clsx('absolute left-3 sm:left-5', touch ? 'bottom-36' : 'bottom-4')}>
        <canvas ref={radarRef} width={170} height={170} className="h-[120px] w-[120px] rounded-full border-2 border-white/20 shadow-[0_0_24px_rgba(42,107,255,0.35)] sm:h-[160px] sm:w-[160px]" />
      </div>

      {/* Velocímetro y estado */}
      <div className={clsx('pc-glass absolute right-3 w-56 p-3 sm:right-5 sm:w-64', touch ? 'bottom-40' : 'bottom-4')}>
        <div className="mb-2 flex items-end justify-between">
          <div><span className="pc-display text-5xl leading-none text-white">{hud.kmh}</span><span className="ml-1 text-xs font-bold text-white/50">KM/H</span></div>
          {hud.nitro > 0 && <Flame size={22} className={hud.nitro > 0.2 ? 'text-[#3fb8ff]' : 'text-white/30'} />}
        </div>
        <div className="flex flex-col gap-2">
          <Bar value={hud.hp / 100} color={hud.hp < 30 ? '#ff3b4e' : hud.hp < 60 ? '#ffb23f' : '#3dff7a'} icon={<Heart size={15} fill="currentColor" />} label="Carrocería" warn={hud.hp < 30} />
          <Bar value={hud.nitro} color="#3fb8ff" icon={<Zap size={15} fill="currentColor" />} label="Nitro" />
        </div>
      </div>

      {/* Controles táctiles */}
      {touch && (
        <>
          <div className="absolute bottom-4 left-3 flex gap-3">
            <TouchBtn k="left" pad={pad} className="h-24 w-24"><ChevronLeft size={44} /></TouchBtn>
            <TouchBtn k="right" pad={pad} className="h-24 w-24"><ChevronRight size={44} /></TouchBtn>
          </div>
          <div className="absolute bottom-4 right-3 flex items-end gap-3">
            <TouchBtn k="nitro" pad={pad} className="h-16 w-16 text-[#3fb8ff]"><Zap size={30} /></TouchBtn>
            <div className="flex flex-col gap-2">
              <TouchBtn k="up" pad={pad} className="h-20 w-24"><ChevronUp size={42} /></TouchBtn>
              <TouchBtn k="down" pad={pad} className="h-12 w-24"><ChevronDown size={30} /></TouchBtn>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { Banknote, Gauge, Play, Siren, Star, Trophy, Volume2, VolumeX, Wrench, Zap } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS, formatMoney, formatTime, SaveData } from '../game/config';

interface Props { save: SaveData; muted: boolean; onPlay(): void; onDiff(id: string): void; onMute(): void }

const KEYS: Array<[string, string]> = [
  ['↑ / W', 'Acelerar'], ['↓ / S', 'Frenar · reversa'], ['← → / A D', 'Girar'], ['Espacio', 'Nitro'], ['Esc / P', 'Pausa'],
];

export default function Menu({ save, muted, onPlay, onDiff, onMute }: Props) {
  return (
    <div className="absolute inset-0 overflow-y-auto">
      <div className="absolute inset-0 bg-gradient-to-r from-[#04060e]/95 via-[#04060e]/70 to-transparent" />
      <button onClick={onMute} aria-label="Sonido"
        className="pc-glass absolute right-4 top-4 z-10 grid h-11 w-11 place-items-center text-white/80 hover:text-white">
        {muted ? <VolumeX size={20} /> : <Volume2 size={20} />}
      </button>
      <div className="relative flex min-h-full max-w-[640px] flex-col justify-center gap-5 px-5 py-8 sm:px-10">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.35em] text-[#7fa6ff]">
            <Siren size={16} className="pc-blink text-[#ff3b4e]" /> Se busca · vivo o en fuga
          </div>
          <h1 className="pc-display pc-title text-6xl sm:text-8xl">Persecución<br /><span className="text-5xl sm:text-7xl">Nocturna</span></h1>
          <p className="mt-4 max-w-md text-sm leading-relaxed text-white/75 sm:text-base">
            Atraviesa la ciudad bajo la lluvia con el botín. Cada billete sube tu nivel de búsqueda: patrullas que embisten,
            controles con pinchos y, a cuatro estrellas, el helicóptero. Despístalos para bajar el calor.
          </p>
        </div>

        <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
          {[
            [Banknote, 'Botín', '#3dff7a'], [Wrench, 'Reparar', '#ffd23f'], [Zap, 'Nitro', '#3fb8ff'], [Star, 'Pintura −1★', '#d45cff'],
          ].map(([Icon, label, color]) => {
            const I = Icon as typeof Star;
            return (
              <div key={label as string} className="pc-glass flex items-center gap-2 px-3 py-2 text-xs font-semibold">
                <I size={16} color={color as string} /> {label as string}
              </div>
            );
          })}
        </div>

        <div>
          <div className="mb-2 text-xs font-bold uppercase tracking-widest text-white/50">Dificultad</div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => (
              <button key={d.id} onClick={() => onDiff(d.id)}
                className={clsx('pc-chip px-3 py-2.5 text-left', save.diff === d.id ? 'bg-white/10' : 'bg-black/30')}
                style={save.diff === d.id ? { borderColor: d.color, boxShadow: `0 0 18px ${d.color}55` } : undefined}>
                <div className="pc-display text-lg" style={{ color: d.color }}>{d.name}</div>
                <div className="text-[11px] leading-tight text-white/60">{d.desc}</div>
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button onClick={onPlay} className="pc-btn pc-btn-main pc-display flex items-center gap-3 px-10 py-4 text-3xl">
            <Play size={28} fill="currentColor" /> Jugar
          </button>
          <div className="pc-glass flex items-center gap-3 px-4 py-2.5">
            <Trophy size={22} className="text-[#ffd23f]" />
            <div>
              <div className="text-[10px] font-bold uppercase tracking-widest text-white/50">Récord</div>
              <div className="pc-mono text-lg font-bold">{save.best.toLocaleString('es-ES')} pts</div>
              <div className="flex items-center gap-2 text-[11px] text-white/55">
                <span className="text-[#ffd23f]">{'★'.repeat(save.bestStars) || '—'}</span>
                <span>{formatTime(save.bestTime)}</span><span>· {formatMoney(save.loot)} total</span>
              </div>
            </div>
          </div>
        </div>

        <div className="pc-glass grid grid-cols-2 gap-x-4 gap-y-1.5 p-3 text-xs sm:grid-cols-3">
          {KEYS.map(([k, v]) => (
            <div key={k} className="flex items-center gap-2"><kbd className="pc-mono rounded bg-white/10 px-1.5 py-0.5 text-[11px] text-white">{k}</kbd><span className="text-white/65">{v}</span></div>
          ))}
          <div className="flex items-center gap-2 text-white/65"><Gauge size={14} /> Táctil: botones en pantalla</div>
        </div>
      </div>
    </div>
  );
}

import { Car, Home, Play, RotateCcw, Siren, Star, Trophy } from 'lucide-react';
import { formatMoney, formatTime } from '../game/config';
import { RunResult } from '../game/engine';

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume(): void; onRestart(): void; onMenu(): void }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-[#03050c]/70 p-4 backdrop-blur-sm">
      <div className="pc-glass pc-pop w-full max-w-xs p-6 text-center">
        <h2 className="pc-display pc-title mb-5 text-5xl">Pausa</h2>
        <div className="flex flex-col gap-3">
          <button onClick={onResume} className="pc-btn pc-btn-main pc-display flex items-center justify-center gap-2 py-3 text-2xl"><Play size={22} fill="currentColor" /> Continuar</button>
          <button onClick={onRestart} className="pc-btn pc-chip flex items-center justify-center gap-2 bg-white/5 py-3"><RotateCcw size={18} /> Reiniciar</button>
          <button onClick={onMenu} className="pc-btn pc-chip flex items-center justify-center gap-2 bg-white/5 py-3"><Home size={18} /> Menú principal</button>
        </div>
        <p className="mt-4 text-xs text-white/45">Esc o P para continuar</p>
      </div>
    </div>
  );
}

interface ResultProps { r: RunResult; record: boolean; best: number; onRetry(): void; onMenu(): void }

export function GameOver({ r, record, best, onRetry, onMenu }: ResultProps) {
  const busted = r.reason === 'busted';
  const rows: Array<[string, string]> = [
    ['Botín', formatMoney(r.money)], ['Tiempo en fuga', formatTime(r.time)],
    ['Patrullas destrozadas', String(r.wrecked)], ['Bonus de tiempo', `${(r.time * 10).toLocaleString('es-ES')} pts`],
  ];
  return (
    <div className="absolute inset-0 grid place-items-center overflow-y-auto bg-gradient-to-b from-[#03050c]/40 to-[#03050c]/85 p-4">
      <div className="pc-glass pc-pop w-full max-w-md p-6 text-center">
        <div className="mb-1 flex justify-center">{busted ? <Siren size={40} className="pc-blink text-[#ff3b4e]" /> : <Car size={40} className="text-[#ff9a2e]" />}</div>
        <h2 className="pc-display pc-title text-5xl sm:text-6xl">{busted ? '¡Arrestado!' : '¡Destrozado!'}</h2>
        <p className="mt-1 text-sm text-white/60">{busted ? 'Te acorralaron. La próxima vez no te detengas.' : 'Tu coche no aguantó más golpes.'}</p>
        <div className="my-4 flex justify-center gap-1">
          {Array.from({ length: 5 }, (_, i) => <Star key={i} size={28} fill="currentColor" className={i < r.stars ? 'text-[#ffd23f]' : 'text-white/15'} />)}
        </div>
        <div className="mb-4 flex flex-col gap-1.5 text-left text-sm">
          {rows.map(([k, v]) => (
            <div key={k} className="flex justify-between border-b border-white/10 pb-1"><span className="text-white/60">{k}</span><span className="pc-mono font-bold">{v}</span></div>
          ))}
        </div>
        <div className="text-[11px] font-bold uppercase tracking-[0.3em] text-white/50">Puntuación</div>
        <div className="pc-display text-5xl text-white" style={{ textShadow: '0 0 20px rgba(255,210,63,0.6)' }}>{r.score.toLocaleString('es-ES')}</div>
        {record
          ? <div className="pc-blink mt-1 flex items-center justify-center gap-2 font-black text-[#ffd23f]"><Trophy size={18} /> ¡NUEVO RÉCORD!</div>
          : <div className="mt-1 text-xs text-white/50">Récord: {best.toLocaleString('es-ES')} pts</div>}
        <div className="mt-5 grid grid-cols-2 gap-3">
          <button onClick={onRetry} className="pc-btn pc-btn-main pc-display flex items-center justify-center gap-2 py-3 text-2xl"><RotateCcw size={20} /> Reintentar</button>
          <button onClick={onMenu} className="pc-btn pc-chip flex items-center justify-center gap-2 bg-white/5 py-3"><Home size={18} /> Menú</button>
        </div>
      </div>
    </div>
  );
}

// Audio procedural con Web Audio API: motor, sirenas, lluvia, helicóptero y efectos.
type Ctx = AudioContext;
class Sound {
  private ctx: Ctx | null = null; private master: GainNode | null = null;
  private engOsc: OscillatorNode | null = null; private engGain: GainNode | null = null; private engFilter: BiquadFilterNode | null = null;
  private sirenOsc: OscillatorNode | null = null; private sirenGain: GainNode | null = null;
  private rainGain: GainNode | null = null; private heliGain: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private sirenPhase = 0;
  muted = false;
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      const ctx = new AC(); this.ctx = ctx;
      this.master = ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.5; this.master.connect(ctx.destination);
      // Ruido blanco reutilizable.
      const len = ctx.sampleRate * 2; this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
