}

// Constantes de la ciudad, dificultad, guardado y utilidades compartidas.
/** Calles en x = i·CELL y z = j·CELL; entre ellas, manzanas de BLOCK de lado. */
export const CELL = 54;
export const HALF_ROAD = 7;
export const BLOCK = CELL - HALF_ROAD * 2;
export const GRID = 5;
/** Límite jugable (±LIMIT en x y z). */
export const LIMIT = GRID * CELL;
export const MAX_STARS = 5;
export interface Difficulty {
  id: string; name: string; desc: string;
  heatRate: number;   // estrellas ganadas por segundo
  copSpeed: number;   // multiplicador de velocidad punta de la policía
  damage: number;     // multiplicador del daño recibido
  maxCops: number;
  color: string;
}
export const DIFFS: Difficulty[] = [
  { id: 'novato', name: 'Novato', desc: 'Patrullas lentas y calor que sube despacio.', heatRate: 0.022, copSpeed: 0.86, damage: 0.7, maxCops: 7, color: '#3ee6a0' },
  { id: 'pro', name: 'Profesional', desc: 'La policía no perdona los errores.', heatRate: 0.034, copSpeed: 0.97, damage: 1, maxCops: 9, color: '#ffc23d' },
  { id: 'leyenda', name: 'Leyenda', desc: 'Cinco estrellas en minutos. Suerte.', heatRate: 0.05, copSpeed: 1.07, damage: 1.25, maxCops: 12, color: '#ff3b5c' },
];
export const diffById = (id: string) => DIFFS.find(d => d.id === id) ?? DIFFS[1];
export interface SaveData { best: number; bestStars: number; bestTime: number; diff: string; runs: number; loot: number }
const KEY = 'nona-police-chase-v1';
const DEFAULT_SAVE: SaveData = { best: 0, bestStars: 0, bestTime: 0, diff: 'pro', runs: 0, loot: 0 };
export function loadSave(): SaveData {
  try {
    const raw = localStorage.getItem(KEY);
    return raw ? { ...DEFAULT_SAVE, ...JSON.parse(raw) } : { ...DEFAULT_SAVE };
  } catch { return { ...DEFAULT_SAVE }; }
}
export function storeSave(s: SaveData) {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* sin almacenamiento */ }
}
export const formatTime = (s: number) => {
  const m = Math.floor(s / 60), r = Math.floor(s % 60);
  return `${m}:${r.toString().padStart(2, '0')}`;
};
export const formatMoney = (n: number) => '$' + Math.round(n).toLocaleString('es-ES');
/** Generador pseudoaleatorio con semilla (ciudad reproducible). */
export function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/** Coordenada de la calle más cercana a v. */
export const nearestRoad = (v: number) => Math.round(v / CELL) * CELL;
export const clampRoadIndex = (i: number) => Math.max(-GRID, Math.min(GRID, i));
/** ¿El punto está sobre asfalto (calle o cruce)? */
export function onRoad(x: number, z: number) {
  return Math.abs(x - nearestRoad(x)) < HALF_ROAD || Math.abs(z - nearestRoad(z)) < HALF_ROAD;
}
/**
 * Colisión círculo-manzana. Devuelve el empuje (nx, nz, profundidad) o null.
 * Como las manzanas están separadas por calles de 14 m, un círculo de radio < 7 solo toca una.
 */
export function blockPush(x: number, z: number, r: number): { nx: number; nz: number; d: number } | null {
  const i = Math.floor(x / CELL), j = Math.floor(z / CELL);
  const x0 = i * CELL + HALF_ROAD, x1 = (i + 1) * CELL - HALF_ROAD;
  const z0 = j * CELL + HALF_ROAD, z1 = (j + 1) * CELL - HALF_ROAD;
  const cx = Math.max(x0, Math.min(x1, x)), cz = Math.max(z0, Math.min(z1, z));
  const dx = x - cx, dz = z - cz, d2 = dx * dx + dz * dz;
  if (d2 >= r * r) return null;
  if (d2 > 1e-6) { const d = Math.sqrt(d2); return { nx: dx / d, nz: dz / d, d: r - d }; }
  // Centro dentro de la manzana: salir por el lado más cercano.
  const opts = [
    { nx: -1, nz: 0, d: x - x0 + r }, { nx: 1, nz: 0, d: x1 - x + r },
    { nx: 0, nz: -1, d: z - z0 + r }, { nx: 0, nz: 1, d: z1 - z + r },
  ];
  return opts.reduce((a, b) => (b.d < a.d ? b : a));
}
/** Punto aleatorio sobre una calle (centro de carril), opcionalmente lejos de (ax, az). */
export function randomRoadPoint(rand: () => number, ax = 0, az = 0, minD = 0, maxD = 1e9) {
  for (let k = 0; k < 40; k++) {
    const along = (rand() * 2 - 1) * (LIMIT - 10);
    const line = (Math.floor(rand() * (GRID * 2 + 1)) - GRID) * CELL;
    const vertical = rand() < 0.5;
    const x = vertical ? line : along, z = vertical ? along : line;
    const d = Math.hypot(x - ax, z - az);
    if (d >= minD && d <= maxD) return { x, z, vertical };
  }
  return { x: ax + minD, z: nearestRoad(az), vertical: false };
}

// Motor principal: escena, cámara cenital inclinada, reglas de persecución, nivel de búsqueda y bucle.
import * as THREE from 'three';
import { CELL, Difficulty, DIFFS, LIMIT, MAX_STARS, rng } from './config';
