type Mode = 'attract' | 'play' | 'paused' | 'over';
export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer; private scene = new THREE.Scene(); private camera: THREE.PerspectiveCamera;
  private city: City; private kit = new CarKit(); private police: PoliceForce; private traffic: Traffic; private pickups: Pickups; private fx = new Fx();
  private player: Car; private head: THREE.SpotLight;
  private rand = rng(Date.now() % 100000);
  private mode: Mode = 'attract'; private diff: Difficulty = DIFFS[1];
  private clock = new THREE.Clock(); private raf = 0; private ro: ResizeObserver; private t = 0;
  private camPos = new THREE.Vector3(0, 60, 30); private camLook = new THREE.Vector3();
  private radar: HTMLCanvasElement | null = null; private hudT = 0; private radarT = 0;
  // Estado de la partida.
  private money = 0; private time = 0; private heat = 1; private nitro = 1; private bust = 0; private evade = 0;
  private auto = { x: 0, z: 0 }; private puncture = 0; private wrecked = 0; private maxStars = 1; private lastStars = 1; private nitroOn = false; private overT = 0;
  constructor(private host: HTMLElement, private ev: GameEvents) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.domElement.style.display = 'block';
    host.appendChild(this.renderer.domElement);
    this.scene.background = lin('#060912');
    this.scene.fog = new THREE.FogExp2(lin('#0a0f1e').getHex(), 0.0088);
    this.camera = new THREE.PerspectiveCamera(46, 1, 1, 600);
    this.scene.add(new THREE.HemisphereLight(lin('#5a6ea8'), lin('#0a0c14'), 0.75 * LIGHT_K));
    const moon = new THREE.DirectionalLight(lin('#9fb4ee'), 0.45 * LIGHT_K); moon.position.set(-40, 80, -30); this.scene.add(moon);
    this.city = new City(); this.scene.add(this.city.group);
    this.police = new PoliceForce(this.kit, this.rand); this.scene.add(this.police.group);
    this.traffic = new Traffic(this.kit, this.rand); this.scene.add(this.traffic.group);
    this.pickups = new Pickups(this.rand, this.kit.glow); this.scene.add(this.pickups.group);
    this.scene.add(this.fx.group);
    this.player = new Car('player', { ...SPECS.player }, buildCar(this.kit, 'player', '#ff7a12'));
    this.scene.add(this.player.mesh.root);
    this.head = new THREE.SpotLight(lin('#fff1d0'), 3 * LIGHT_K, 48, 0.55, 0.6, LIGHT_DECAY);
    this.head.position.set(0, 1, -2.6); this.head.target.position.set(0, 0, -22);
    this.player.mesh.root.add(this.head, this.head.target);
