  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false);
    this.renderer.domElement.style.width = '100%'; this.renderer.domElement.style.height = '100%';
    this.camera.aspect = w / h; this.camera.fov = w / h < 0.8 ? 62 : 46; this.camera.updateProjectionMatrix();
  }
  attachRadar(c: HTMLCanvasElement | null) { this.radar = c; }
  /** Menú: el fugitivo conduce solo por la ciudad con las patrullas detrás. */
  toAttract() {
    this.mode = 'attract'; this.police.clear(); this.pickups.reset(0, 0, 24);
    this.player.place(3.4, 30, 0); this.player.hp = 100; this.auto = { x: 0, z: 0 };
    this.camPos.set(-18.6, 50, 58); this.camLook.set(-12.6, 0, 34);
    for (let i = 0; i < 4; i++) this.police.spawn('police', i % 2 ? 3.4 : -3.4, 44 + i * 9, 0);
  }
  private autopilot(dt: number) {
    const p = this.player, a = this.auto;
    if (Math.hypot(a.x - p.x, a.z - p.z) < 8) { // siguiente cruce al azar, sin dar media vuelta
      const fx = -Math.sin(p.h), fz = -Math.cos(p.h);
      const opts = [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(([dx, dz]) => dx * fx + dz * fz > -0.5 && Math.abs(a.x + dx * CELL) < LIMIT && Math.abs(a.z + dz * CELL) < LIMIT);
      const [dx, dz] = opts[Math.floor(this.rand() * opts.length)] ?? [0, -1]; a.x += dx * CELL; a.z += dz * CELL;
    }
    const want = Math.atan2(-(a.x - p.x), -(a.z - p.z)), d = Math.atan2(Math.sin(want - p.h), Math.cos(want - p.h));
    p.drive(Math.abs(d) > 0.6 ? 0.35 : 0.8, 0, Math.max(-1, Math.min(1, d * 2.5)), dt); p.integrate(dt);
    this.police.active.forEach(c => collideCars(p, c.car));
  }
  newGame(diff: Difficulty) {
    this.diff = diff; this.mode = 'play'; this.input.reset();
    Object.assign(this, { money: 0, time: 0, heat: 1.15, nitro: 1, bust: 0, evade: 0, puncture: 0, wrecked: 0, maxStars: 1, lastStars: 1, overT: 0 });
    this.player.spec = { ...SPECS.player }; this.player.hp = 100; this.player.grip = 1;
    this.player.place(3.4, 2.5 * CELL, 0);
    this.police.clear(); this.pickups.reset(this.player.x, this.player.z);
    // La persecución empieza ya: dos patrullas pegadas detrás y otra cruzando por delante.
    this.police.spawn('police', -3.4, 2.5 * CELL + 9, 0);
    this.police.spawn('police', 3.4, 2.5 * CELL + 15, 0);
    this.police.spawn('police', -24, 2 * CELL + 3.4, -Math.PI / 2);
    this.traffic.civs.forEach(c => this.traffic.respawn(c, this.player.x, this.player.z, 25, 120));
    this.camPos.set(this.player.x, 60, this.player.z + 28);
    this.ev.onEvent('¡Huye de la policía!', '#ffd23f');
  }
  setPaused(p: boolean) { if (this.mode === 'play' || this.mode === 'paused') this.mode = p ? 'paused' : 'play'; }
  private loop = () => {
    this.raf = requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, this.clock.getDelta());
    if (this.mode !== 'paused') this.step(dt);
    this.renderer.render(this.scene, this.camera);
  };
  private step(dt: number) {
    this.t += dt;
    const p = this.player, playing = this.mode === 'play';
    if (playing) this.updatePlay(dt);
    else if (this.mode === 'attract') this.autopilot(dt);
    else if (this.mode === 'over') { this.overT += dt; p.drive(0, 1, 0, dt); p.integrate(dt); if (p.hp <= 0 && Math.random() < 0.6) this.fx.smokeAt(p.x, p.z, true, true); }
    this.police.update(dt, this.t, p, playing ? this.stars : 2, this.diff, playing);
    if (this.mode === 'over') this.police.active.forEach(c => { c.car.drive(0, 1, 0, dt); });
    this.traffic.update(dt, p.x, p.z);
    this.city.update(this.t);
    this.updateCamera(dt);
    const sh = this.fx.update(dt, this.camLook.x, this.camLook.z, 4);
    this.camera.position.x += sh.x; this.camera.position.y += sh.y;
    // Sonido ambiente.
    const nearest = this.police.active.reduce((m, c) => Math.min(m, Math.hypot(c.car.x - p.x, c.car.z - p.z)), 999);
    const heliN = this.police.heli.visible ? Math.max(0, 1 - this.police.heli.position.distanceTo(p.mesh.root.position) / 90) : 0;
    sound.update(dt, Math.min(1, p.speed / p.spec.maxSpeed), this.nitroOn, playing ? Math.max(0, 1 - nearest / 90) : 0, playing ? heliN : 0, playing);
    // HUD y radar a ~10 Hz.
    this.hudT -= dt; this.radarT -= dt;
    if (this.radarT <= 0 && this.radar && this.mode !== 'attract') { this.radarT = 0.1; this.drawRadar(); }
    if (this.hudT <= 0 && playing) { this.hudT = 0.1; this.ev.onHud(this.hud()); }
  }
  private get stars() { return Math.max(1, Math.min(MAX_STARS, Math.floor(this.heat))); }
  private updatePlay(dt: number) {
    const p = this.player, inp = this.input, d = this.diff;
    this.time += dt;
    // Nitro.
    const wantNitro = inp.nitro && this.nitro > 0.02 && inp.throttle > 0;
    if (wantNitro && !this.nitroOn) sound.nitro();
    this.nitroOn = wantNitro;
    this.nitro = wantNitro ? Math.max(0, this.nitro - dt * 0.32) : Math.min(1, this.nitro + dt * 0.025);
    if (wantNitro) this.fx.nitro(p.x + Math.sin(p.h) * 2.4, p.z + Math.cos(p.h) * 2.4, Math.sin(p.h), Math.cos(p.h));
    // Pinchazo.
    this.puncture = Math.max(0, this.puncture - dt);
    p.grip = this.puncture > 0 ? 0.4 : 1;
    p.drive(inp.throttle, inp.brake, inp.steer, dt, wantNitro ? 1.9 : 1, this.puncture > 0 ? 0.7 : 1);
    const wall = p.integrate(dt);
    if (wall > 7) this.hit(wall - 7, 0.9, p.x - Math.sin(p.h) * 2, p.z - Math.cos(p.h) * 2);
    // Choques con la policía.
    for (const c of this.police.active) {
      const rel = collideCars(p, c.car);
      if (rel > 3) {
        this.hit(rel, c.state === 'block' ? 0.9 : 0.65, (p.x + c.car.x) / 2, (p.z + c.car.z) / 2);
        c.car.hp -= rel * (wantNitro ? 3 : 1.7); this.heat += 0.03;
        if (c.car.hp <= 0) this.wreckCop(c);
