    }
    // Tráfico civil.
    for (const civ of this.traffic.civs) {
      const rel = collideCars(p, civ.car);
      if (rel > 3) { this.traffic.knock(civ.car); this.hit(rel, 0.3, civ.car.x, civ.car.z); this.heat += 0.06; }
      for (const c of this.police.active) if (Math.abs(c.car.x - civ.car.x) < 5 && Math.abs(c.car.z - civ.car.z) < 5 && collideCars(c.car, civ.car) > 3) this.traffic.knock(civ.car);
    }
    // Pinchos.
    for (const s of this.police.spikes) {
      if (s.life > 0 && Math.abs(p.x - s.x) < (s.vertical ? 7 : 1.8) && Math.abs(p.z - s.z) < (s.vertical ? 1.8 : 7)) {
        s.life = 0.01; this.puncture = 4.5; p.hp -= 8 * d.damage; sound.spikes(); this.fx.burst(p.x, p.z, 14);
        this.ev.onEvent('¡Pinchazo!', '#ff5a3c');
      }
