    // Botín y mejoras.
    for (const k of this.pickups.update(dt, this.t, p.x, p.z, p.spec.radius)) {
      if (k === 'cash') {
        const v = Math.round((100 + this.rand() * 150) * (1 + (this.stars - 1) * 0.5) / 10) * 10;
        this.money += v; this.heat += 0.07; sound.cash(); this.ev.onEvent(`+$${v}`, PICKUP_INFO.cash.color);
      } else {
        sound.power();
        if (k === 'repair') { p.hp = Math.min(100, p.hp + 40); this.ev.onEvent('Reparación +40', PICKUP_INFO.repair.color); }
        if (k === 'nitro') { this.nitro = 1; this.ev.onEvent('¡Nitro lleno!', PICKUP_INFO.nitro.color); }
        if (k === 'paint') {
          this.heat = Math.max(1, this.heat - 1); this.evade = 0;
