    if (st > this.lastStars) {
      sound.star(); this.ev.onEvent(`Nivel de búsqueda ${'★'.repeat(st)}`, '#ffd23f');
      if (st === 3) this.ev.onEvent('¡Controles con pinchos!', '#ff5a3c');
