    c.car.mesh.paint.color.copy(lin('#3a3a40'));
    const bonus = 150 * this.stars; this.money += bonus; this.heat += 0.25;
    this.fx.burst(c.car.x, c.car.z, 30); for (let i = 0; i < 8; i++) this.fx.smokeAt(c.car.x, c.car.z, true, true);
    this.ev.onEvent(`¡Patrulla destrozada! +$${bonus}`, '#ff9a2e');
  }
  private end(reason: 'busted' | 'wrecked') {
    this.mode = 'over'; this.nitroOn = false;
    if (reason === 'busted') sound.bust(); else sound.crash(1);
    this.fx.shake(1.5);
    const time = Math.floor(this.time);
    this.ev.onHud(this.hud());
    this.ev.onOver({ money: this.money, time, score: this.money + time * 10, stars: this.maxStars, wrecked: this.wrecked, reason });
  }
  private hud(): HudState {
    const p = this.player;
    return {
      money: this.money, time: this.time, heat: this.heat, stars: this.stars, hp: Math.max(0, p.hp), nitro: this.nitro,
      kmh: Math.round(p.speed * 3.6 * 1.4), bust: Math.min(1, this.bust), evade: this.evade / 7, heli: this.police.heliActive,
      lit: this.police.heliLit, cops: this.police.active.length, puncture: this.puncture > 0,
    };
  }
  private updateCamera(dt: number) {
    const p = this.player;
    let target: THREE.Vector3, look: THREE.Vector3;
    if (this.mode === 'attract') {
      look = new THREE.Vector3(p.x - 16, 0, p.z + 4);
      target = new THREE.Vector3(look.x - 6, 50, look.z + 24);
    } else {
      const lead = 0.3, sp = p.speed;
