}
const RAIN = 900;
export class Fx {
  readonly group = new THREE.Group();
  private sparks: Pool; private smoke: Pool; private flames: Pool; private splash: Pool;
  private rain: THREE.LineSegments; private rainPos: Float32Array; private rainSeed: Float32Array;
  private tex: THREE.Texture[] = [];
  private shakeAmt = 0;
  private cSpark = lin('#ffc85a'); private cSmoke = new THREE.Color(0.32, 0.33, 0.36); private cDark = new THREE.Color(0.1, 0.1, 0.11);
  private cFlame = lin('#4fb8ff'); private cFire = lin('#ff7a1a'); private cSplash = lin('#9fb8e0');
  constructor() {
    const dot = radialTexture([[0, 'rgba(255,255,255,1)'], [0.35, 'rgba(255,255,255,0.6)'], [1, 'rgba(255,255,255,0)']]);
    const puff = radialTexture([[0, 'rgba(255,255,255,0.9)'], [0.6, 'rgba(255,255,255,0.35)'], [1, 'rgba(255,255,255,0)']]);
    this.tex.push(dot, puff);
    this.sparks = new Pool(220, 0.9, dot, true, 26, 1.5);
    this.flames = new Pool(160, 2.4, dot, true, -2, 4);
    this.smoke = new Pool(140, 5, puff, false, -3, 1.2);
    this.splash = new Pool(200, 0.7, dot, true, 14, 1);
