    for (let i = 0; i < RAIN; i++) this.rainSeed.set([Math.random() * 130 - 65, Math.random() * 45, Math.random() * 110 - 60], i * 3);
    const rg = new THREE.BufferGeometry(); rg.setAttribute('position', new THREE.BufferAttribute(this.rainPos, 3));
    this.rain = new THREE.LineSegments(rg, new THREE.LineBasicMaterial({ color: lin('#a8bde6'), transparent: true, opacity: 0.38, depthWrite: false }));
    this.rain.frustumCulled = false;
    this.group.add(this.sparks.points, this.flames.points, this.smoke.points, this.splash.points, this.rain);
  }
  burst(x: number, z: number, power: number) {
    const n = Math.min(40, 8 + Math.floor(power * 2));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, s = 4 + Math.random() * power * 0.8;
      this.sparks.emit(x, 0.8, z, Math.cos(a) * s, 3 + Math.random() * 7, Math.sin(a) * s, 0.4 + Math.random() * 0.5, this.cSpark);
    }
    this.shake(Math.min(1.4, power * 0.05));
  }
  smokeAt(x: number, z: number, dark: boolean, fire = false) {
    this.smoke.emit(x + (Math.random() - 0.5), 1.2, z + (Math.random() - 0.5), (Math.random() - 0.5) * 2, 2 + Math.random() * 2, (Math.random() - 0.5) * 2, 1.4 + Math.random(), dark ? this.cDark : this.cSmoke);
