  }
  /** Llama azul de nitro por el escape (x, z = trasera del coche, dx, dz = dirección hacia atrás). */
  nitro(x: number, z: number, dx: number, dz: number) {
    for (let i = 0; i < 2; i++)
      this.flames.emit(x + (Math.random() - 0.5) * 0.8, 0.7, z + (Math.random() - 0.5) * 0.8, dx * 12, 0.5, dz * 12, 0.22 + Math.random() * 0.1, this.cFlame);
  }
  shake(a: number) { this.shakeAmt = Math.max(this.shakeAmt, a); }
  /** Devuelve el desplazamiento de cámara por sacudida. */
  update(dt: number, cx: number, cz: number, wind: number) {
    this.sparks.update(dt); this.flames.update(dt); this.smoke.update(dt); this.splash.update(dt);
    // Lluvia: cada gota cae en bucle dentro de una caja que sigue a la cámara.
    for (let i = 0; i < RAIN; i++) {
      const j = i * 3;
      let y = this.rainSeed[j + 1] - dt * 48;
      if (y < 0) {
        y += 45;
        if (i % 5 === 0) this.splash.emit(this.rainPos[i * 6], 0.15, this.rainPos[i * 6 + 2], (Math.random() - 0.5) * 3, 3, (Math.random() - 0.5) * 3, 0.25, this.cSplash);
      }
      this.rainSeed[j + 1] = y;
      const wx = ((this.rainSeed[j] + wind * y * 0.1 - cx) % 130 + 195) % 130 - 65 + cx;
      const wz = ((this.rainSeed[j + 2] - cz) % 110 + 170) % 110 - 60 + cz;
      this.rainPos.set([wx, y, wz, wx + wind * 0.05, y + 1.8, wz - 0.4], i * 6);
    }
    this.rain.geometry.attributes.position.needsUpdate = true;
    const s = this.shakeAmt; this.shakeAmt = Math.max(0, s - dt * 2.5);
