  }
  dispose() {
    [this.sparks, this.flames, this.smoke, this.splash].forEach(p => { p.points.geometry.dispose(); (p.points.material as THREE.Material).dispose(); });
    this.rain.geometry.dispose(); (this.rain.material as THREE.Material).dispose();
    this.tex.forEach(t => t.dispose());
  }
}

// Entrada: teclado (flechas / WASD) escuchado en window + botones táctiles virtuales.
export interface VirtualPad { up: boolean; down: boolean; left: boolean; right: boolean; nitro: boolean }
export class Input {
  private keys = new Set<string>();
  readonly virtual: VirtualPad = { up: false, down: false, left: false, right: false, nitro: false };
  private onDown = (e: KeyboardEvent) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };
  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }
  private any(...codes: string[]) { return codes.some(c => this.keys.has(c)); }
  get throttle() { return this.virtual.up || this.any('ArrowUp', 'KeyW') ? 1 : 0; }
  get brake() { return this.virtual.down || this.any('ArrowDown', 'KeyS') ? 1 : 0; }
  get steer() {
    return (this.virtual.left || this.any('ArrowLeft', 'KeyA') ? 1 : 0) - (this.virtual.right || this.any('ArrowRight', 'KeyD') ? 1 : 0);
  }
  get nitro() { return this.virtual.nitro || this.any('Space', 'ShiftLeft', 'ShiftRight'); }
  reset() {
    this.keys.clear();
    Object.assign(this.virtual, { up: false, down: false, left: false, right: false, nitro: false });
  }
  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

// Radar 2D: calles, botín, patrullas (parpadeo rojo/azul), helicóptero y jugador.
import { CELL, GRID, LIMIT } from './config';
import { PICKUP_INFO, PickupKind } from './pickups';
export interface RadarData {
  px: number; pz: number; h: number;
  cops: Array<{ x: number; z: number; wreck: boolean }>;
  items: Array<{ x: number; z: number; kind: PickupKind }>;
  heli: { x: number; z: number } | null;
  t: number;
}
const RANGE = 110;
export function drawRadar(c: HTMLCanvasElement, d: RadarData) {
  const g = c.getContext('2d'); if (!g) return;
  const S = c.width, k = S / (RANGE * 2), cx = S / 2, cy = S / 2;
  const X = (x: number) => cx + (x - d.px) * k, Y = (z: number) => cy + (z - d.pz) * k;
  g.clearRect(0, 0, S, S);
  g.save();
  g.beginPath(); g.arc(cx, cy, S / 2 - 1, 0, Math.PI * 2); g.clip();
  g.fillStyle = 'rgba(6,10,22,0.86)'; g.fillRect(0, 0, S, S);
  // Calles.
  g.strokeStyle = 'rgba(120,150,210,0.35)'; g.lineWidth = 14 * k;
  for (let i = -GRID; i <= GRID; i++) {
    const v = i * CELL;
    g.beginPath(); g.moveTo(X(v), Y(-LIMIT)); g.lineTo(X(v), Y(LIMIT)); g.stroke();
    g.beginPath(); g.moveTo(X(-LIMIT), Y(v)); g.lineTo(X(LIMIT), Y(v)); g.stroke();
  }
  // Borde de la ciudad.
  g.strokeStyle = 'rgba(255,80,90,0.5)'; g.lineWidth = 2; g.strokeRect(X(-LIMIT), Y(-LIMIT), LIMIT * 2 * k, LIMIT * 2 * k);
  // Botín.
  for (const it of d.items) {
    const x = X(it.x), y = Y(it.z); if (x < 0 || y < 0 || x > S || y > S) continue;
    g.fillStyle = PICKUP_INFO[it.kind].color; g.beginPath(); g.arc(x, y, it.kind === 'cash' ? 2.4 : 3.4, 0, Math.PI * 2); g.fill();
  }
  // Patrullas.
  const blink = Math.floor(d.t * 6) % 2 === 0;
  for (const cp of d.cops) {
    let x = X(cp.x), y = Y(cp.z);
    const out = Math.hypot(x - cx, y - cy) > S / 2 - 6;
    if (out) { const a = Math.atan2(y - cy, x - cx); x = cx + Math.cos(a) * (S / 2 - 6); y = cy + Math.sin(a) * (S / 2 - 6); }
    g.fillStyle = cp.wreck ? '#666b78' : blink ? '#ff3344' : '#3a74ff';
    g.beginPath(); g.arc(x, y, out ? 2.6 : 4, 0, Math.PI * 2); g.fill();
  }
  if (d.heli) {
    g.strokeStyle = '#ffffff'; g.lineWidth = 2; g.beginPath(); g.arc(X(d.heli.x), Y(d.heli.z), 6, 0, Math.PI * 2); g.stroke();
  }
  // Jugador (flecha).
  g.translate(cx, cy); g.rotate(-d.h);
  g.fillStyle = '#ffd23f'; g.strokeStyle = '#000'; g.lineWidth = 1.5;
  g.beginPath(); g.moveTo(0, -8); g.lineTo(6, 6); g.lineTo(0, 3); g.lineTo(-6, 6); g.closePath(); g.fill(); g.stroke();
  g.restore();
}

// Botín y mejoras repartidos por las calles: dinero, reparación, nitro y pintura (pierde una estrella).
import * as THREE from 'three';
import { randomRoadPoint } from './config';
import { canvasTexture, glowMaterial, lin } from './three-compat';
export type PickupKind = 'cash' | 'repair' | 'nitro' | 'paint';
export const PICKUP_INFO: Record<PickupKind, { color: string; label: string; glyph: string }> = {
  cash: { color: '#3dff7a', label: 'Botín', glyph: '$' },
  repair: { color: '#ffd23f', label: 'Reparación', glyph: '+' },
  nitro: { color: '#3fb8ff', label: 'Nitro', glyph: 'N' },
  paint: { color: '#d45cff', label: 'Pintura', glyph: '★' },
};
interface Pickup { kind: PickupKind; sprite: THREE.Sprite; ring: THREE.Mesh; x: number; z: number; phase: number }
function badge(kind: PickupKind) {
  const { color, glyph } = PICKUP_INFO[kind];
  return canvasTexture(128, 128, g => {
    const gr = g.createRadialGradient(64, 64, 10, 64, 64, 64);
    gr.addColorStop(0, color); gr.addColorStop(0.62, color); gr.addColorStop(0.64, 'rgba(255,255,255,0.95)'); gr.addColorStop(0.72, 'rgba(255,255,255,0.0)');
    g.fillStyle = gr; g.beginPath(); g.arc(64, 64, 64, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#0b0f1a'; g.font = 'bold 64px Arial Black, Arial, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(glyph, 64, 68);
    if (kind === 'paint') { g.fillStyle = '#0b0f1a'; g.fillRect(34, 60, 60, 8); }
  });
}
export class Pickups {
  readonly group = new THREE.Group();
  private items: Pickup[] = [];
  private tex: Record<PickupKind, THREE.Texture>;
  private ringMat: Record<PickupKind, THREE.MeshBasicMaterial>;
  private ringGeo = new THREE.RingGeometry(1.6, 2.3, 28).rotateX(-Math.PI / 2);
  constructor(private rand: () => number, ringTex: THREE.Texture) {
    const kinds: PickupKind[] = ['cash', 'repair', 'nitro', 'paint'];
    this.tex = {} as Record<PickupKind, THREE.Texture>; this.ringMat = {} as Record<PickupKind, THREE.MeshBasicMaterial>;
    kinds.forEach(k => { this.tex[k] = badge(k); this.ringMat[k] = glowMaterial(ringTex, PICKUP_INFO[k].color, 0.9); });
  }
  private pickKind(): PickupKind {
    const r = this.rand();
    return r < 0.72 ? 'cash' : r < 0.84 ? 'nitro' : r < 0.94 ? 'repair' : 'paint';
  }
  private add(kind: PickupKind, x: number, z: number) {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.tex[kind], depthWrite: false, transparent: true, color: lin('#ffffff') }));
    sprite.scale.set(3.4, 3.4, 1);
    const ring = new THREE.Mesh(this.ringGeo, this.ringMat[kind]);
    this.group.add(sprite, ring);
    this.items.push({ kind, sprite, ring, x, z, phase: this.rand() * 6 });
  }
  private place(it: Pickup, x: number, z: number) {
    it.x = x; it.z = z; it.ring.position.set(x, 0.12, z);
  }
  /** Reparte el botín inicial alrededor del jugador (con algo de dinero justo delante). */
  reset(px: number, pz: number, count = 30) {
    this.clear();
    for (let i = 0; i < 4; i++) this.add('cash', px + (i % 2 ? 2.5 : -2.5), pz - 22 - i * 16);
    for (let i = 0; i < count; i++) { const p = randomRoadPoint(this.rand, px, pz, 20, 160); this.add(this.pickKind(), p.x, p.z); }
    this.items.forEach(it => this.place(it, it.x, it.z));
  }
  /** Anima y comprueba recogida. Devuelve los tipos recogidos este frame. */
  update(dt: number, t: number, px: number, pz: number, radius: number) {
    const got: PickupKind[] = [];
    for (const it of this.items) {
      const dx = it.x - px, dz = it.z - pz, d = Math.hypot(dx, dz);
      it.sprite.position.set(it.x, 2.2 + Math.sin(t * 3 + it.phase) * 0.35, it.z);
      const s = 3.2 + Math.sin(t * 5 + it.phase) * 0.25; it.sprite.scale.set(s, s, 1);
      it.ring.rotation.y = t * 1.5 + it.phase;
      if (d < radius + 1.4) {
        got.push(it.kind);
        const k = this.pickKind(); it.kind = k;
        (it.sprite.material as THREE.SpriteMaterial).map = this.tex[k]; it.ring.material = this.ringMat[k];
        const p = randomRoadPoint(this.rand, px, pz, 50, 140); this.place(it, p.x, p.z);
      } else if (d > 175) {
        const p = randomRoadPoint(this.rand, px, pz, 50, 140); this.place(it, p.x, p.z);
      }
    }
    return got;
  }
  /** Posiciones para el minimapa. */
  get list() { return this.items.map(i => ({ x: i.x, z: i.z, kind: i.kind })); }
  clear() { this.items.forEach(i => { this.group.remove(i.sprite, i.ring); i.sprite.material.dispose(); }); this.items = []; }
  dispose() {
    this.clear(); this.ringGeo.dispose();
    Object.values(this.tex).forEach(t => t.dispose()); Object.values(this.ringMat).forEach(m => m.dispose());
  }
}

