 * Caída de Point/SpotLight: r170 usa 1/d^decay·ventana suave y r128 (1-d/dist)^decay.
 * Con 0 en r170 y 0.5 en r128 la caída visible es casi idéntica.
 */
export const LIGHT_DECAY = Number(THREE.REVISION) >= 155 ? 0 : 0.5;
/** Color sRGB (#hex) → lineal para materiales, luces, niebla e instancias. */
export const lin = (c: string | number) => new THREE.Color(c).convertSRGBToLinear();
export function setupRenderer(r: THREE.WebGLRenderer) {
