// Tráfico civil: coches que circulan por su carril y salen volando si los embistes.
import * as THREE from 'three';
import { LIMIT, randomRoadPoint } from './config';
import { buildCar, Car, CarKit, SPECS } from './vehicles';
const COLORS = ['#e8c21c', '#e8c21c', '#c8ccd6', '#2d6fd8', '#b8262f', '#2fa36b', '#7a3fd0', '#e2e2e2', '#d8722a'];
const LANE = 3.4;
interface Civ { car: Car; vertical: boolean; dir: number; line: number; speed: number; loose: number }
export class Traffic {
  readonly group = new THREE.Group();
  civs: Civ[] = [];
  constructor(private kit: CarKit, private rand: () => number, count = 14) {
    for (let i = 0; i < count; i++) {
      const car = new Car('civil', { ...SPECS.civil }, buildCar(kit, 'civil', COLORS[Math.floor(rand() * COLORS.length)]));
      this.group.add(car.mesh.root);
      const c: Civ = { car, vertical: true, dir: 1, line: 0, speed: 9, loose: 0 };
      this.civs.push(c);
      this.respawn(c, 0, 0, 0, LIMIT * 1.4);
    }
  }
  /** Recoloca un coche sobre su carril correcto en una calle aleatoria. */
  respawn(c: Civ, px: number, pz: number, minD: number, maxD: number) {
    const pt = randomRoadPoint(this.rand, px, pz, minD, maxD);
    c.vertical = pt.vertical; c.dir = this.rand() < 0.5 ? 1 : -1; c.line = pt.vertical ? pt.x : pt.z;
    c.speed = 7 + this.rand() * 6; c.loose = 0; c.car.hp = 100;
    this.setOnLane(c, pt.vertical ? pt.z : pt.x);
  }
  private setOnLane(c: Civ, along: number) {
    const car = c.car;
    if (c.vertical) { car.x = c.line + (c.dir < 0 ? LANE : -LANE); car.z = along; car.h = c.dir < 0 ? 0 : Math.PI; }
    else { car.z = c.line + (c.dir > 0 ? LANE : -LANE); car.x = along; car.h = c.dir > 0 ? -Math.PI / 2 : Math.PI / 2; }
    car.sync();
  }
  update(dt: number, px: number, pz: number) {
    for (const c of this.civs) {
      const car = c.car;
      if (c.loose > 0) { // tras un golpe: física libre hasta detenerse
        c.loose += dt; car.drive(0, 1, 0, dt); car.integrate(dt);
        if (c.loose > 8 && Math.hypot(car.x - px, car.z - pz) > 70) this.respawn(c, px, pz, 60, 110);
        continue;
      }
      let along = c.vertical ? car.z : car.x;
      along += c.dir * c.speed * dt;
      if (Math.abs(along) > LIMIT) { c.dir = -c.dir; along = Math.sign(along) * LIMIT; }
      this.setOnLane(c, along);
      car.vx = c.vertical ? 0 : c.dir * c.speed; car.vz = c.vertical ? c.dir * c.speed : 0;
      if (Math.hypot(car.x - px, car.z - pz) > 150) this.respawn(c, px, pz, 60, 120);
    }
  }
  /** Marca el coche como suelto tras un choque. */
  knock(car: Car) {
    const c = this.civs.find(v => v.car === car); if (c && c.loose === 0) c.loose = 0.01;
  }
  dispose() { this.civs.forEach(c => c.car.mesh.owned.forEach(m => m.dispose())); this.civs = []; }
}

