export class Car {
  x = 0; z = 0; h = 0; vx = 0; vz = 0; hp = 100; grip = 1; roll = 0;
  constructor(public kind: CarKind, public spec: CarSpec, public mesh: CarMesh) {}
  get speed() { return Math.hypot(this.vx, this.vz); }
  get fwd() { return -Math.sin(this.h) * this.vx - Math.cos(this.h) * this.vz; }
  place(x: number, z: number, h: number) { this.x = x; this.z = z; this.h = h; this.vx = 0; this.vz = 0; this.sync(); }
  /** Control arcade: throttle/brake 0..1, steer −1..1 (positivo = izquierda), boost multiplica potencia. */
  drive(throttle: number, brake: number, steer: number, dt: number, boost = 1, topMul = 1) {
    const s = this.spec, fx = -Math.sin(this.h), fz = -Math.cos(this.h), rx = Math.cos(this.h), rz = -Math.sin(this.h);
