    if (brake > 0) vF -= (vF > 1 ? s.accel * 2.2 : s.accel * 0.6) * brake * dt;
    if (!throttle && !brake) vF -= vF * 0.6 * dt;
    vF = Math.max(-s.maxSpeed * 0.35, Math.min(top, vF));
    if (vF > top) vF += (top - vF) * 2 * dt;
    const drift = brake > 0 && Math.abs(steer) > 0 && vF > 12 ? 0.35 : 1;
    vR *= Math.exp(-s.grip * this.grip * drift * dt);
    const k = Math.max(-1, Math.min(1, vF / 7)) * (1 - 0.3 * Math.min(1, Math.abs(vF) / s.maxSpeed));
    this.h += steer * s.turn * k * dt * (drift < 1 ? 1.35 : 1);
    const nfx = -Math.sin(this.h), nfz = -Math.cos(this.h), nrx = Math.cos(this.h), nrz = -Math.sin(this.h);
