}

.pc-root { font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; user-select: none; -webkit-user-select: none; touch-action: none; color: #e9eefc; }
.pc-display { font-family: Impact, 'Arial Black', 'Helvetica Neue', Arial, sans-serif; letter-spacing: 0.02em; text-transform: uppercase; }
.pc-mono { font-family: 'SFMono-Regular', Consolas, 'Courier New', monospace; font-variant-numeric: tabular-nums; }

.pc-title {
  color: #fff; line-height: 0.88;
  text-shadow: -3px 0 0 #ff2a3d, 3px 0 0 #2a6bff, 0 0 28px rgba(255, 42, 61, 0.55), 0 0 48px rgba(42, 107, 255, 0.45);
  animation: pc-siren 1.1s steps(1) infinite;
}
@keyframes pc-siren {
  0% { text-shadow: -3px 0 0 #ff2a3d, 3px 0 0 #2a6bff, -10px 0 34px rgba(255, 42, 61, 0.8), 0 0 40px rgba(42, 107, 255, 0.2); }
  50% { text-shadow: -3px 0 0 #ff2a3d, 3px 0 0 #2a6bff, 10px 0 34px rgba(42, 107, 255, 0.85), 0 0 40px rgba(255, 42, 61, 0.2); }
}

.pc-glass { background: linear-gradient(160deg, rgba(14, 20, 40, 0.86), rgba(6, 9, 20, 0.9)); border: 1px solid rgba(160, 185, 255, 0.18); border-radius: 14px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.06); backdrop-filter: blur(6px); }
.pc-chip { border: 1px solid rgba(160, 185, 255, 0.25); border-radius: 10px; transition: all 0.15s; }
.pc-chip:hover { border-color: rgba(255, 255, 255, 0.6); }

.pc-btn { position: relative; border-radius: 12px; font-weight: 900; transition: transform 0.08s, filter 0.15s, box-shadow 0.15s; }
.pc-btn:hover { filter: brightness(1.12); }
.pc-btn:active { transform: translateY(2px) scale(0.98); }
.pc-btn-main { background: linear-gradient(90deg, #ff2a3d, #b3123f 48%, #1b3fd8 52%, #2a6bff); box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.85), 0 0 26px rgba(255, 42, 61, 0.55), 0 0 40px rgba(42, 107, 255, 0.4); color: #fff; }

.pc-vignette { pointer-events: none; background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0) 50%, rgba(2, 4, 12, 0.6) 100%); }
.pc-scan { pointer-events: none; background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 3px); }

.pc-star { color: rgba(255, 255, 255, 0.18); transition: color 0.2s, transform 0.2s; }
.pc-star.on { color: #ffd23f; filter: drop-shadow(0 0 6px rgba(255, 210, 63, 0.8)); }
.pc-star.flash { animation: pc-blink 0.5s steps(2) infinite; }

@keyframes pc-blink { 50% { opacity: 0.3; } }
.pc-blink { animation: pc-blink 0.6s steps(2) infinite; }
@keyframes pc-toast { 0% { transform: translateY(16px) scale(0.85); opacity: 0; } 15% { transform: translateY(0) scale(1.05); opacity: 1; } 80% { opacity: 1; } 100% { transform: translateY(-18px); opacity: 0; } }
.pc-toast { animation: pc-toast 1.6s ease-out both; }
@keyframes pc-pop { 0% { transform: scale(1.8); opacity: 0; } 40% { transform: scale(0.95); opacity: 1; } 100% { transform: scale(1); opacity: 1; } }
.pc-pop { animation: pc-pop 0.5s cubic-bezier(0.2, 0.9, 0.3, 1.2) both; }
@keyframes pc-alarm { 0%, 100% { box-shadow: inset 0 0 90px rgba(255, 30, 50, 0.55); } 50% { box-shadow: inset 0 0 90px rgba(40, 90, 255, 0.55); } }
.pc-alarm { pointer-events: none; animation: pc-alarm 0.6s linear infinite; }
.pc-hurt { pointer-events: none; box-shadow: inset 0 0 120px rgba(255, 20, 30, 0.45); }
